import React from "react"; 
import { useTable, usePagination } from "react-table";
import { CSVLink } from "react-csv";

const TableWithExport = ({ data, columns }) => {
  const {
    getTableProps,
    getTableBodyProps,
    headerGroups,
    rows,
    prepareRow,
    canPreviousPage,
    canNextPage,
    pageOptions,
    pageIndex,
    pageSize,
    gotoPage,
    nextPage,
    previousPage,
    setPageSize,
  } = useTable(
    {
      columns,
      data,
    },
    usePagination
  );

  // Filtrar os dados visíveis da página atual
  const currentPageData = rows.slice(pageIndex * pageSize, (pageIndex + 1) * pageSize);

  // Função para gerar o CSV com os dados visíveis
  const generateCSVData = () => {
    return currentPageData.map(row => {
      prepareRow(row);
      return row.cells.reduce((acc, cell) => {
        acc[cell.column.id] = cell.value;
        return acc;
      }, {});
    });
  };

  return (
    <div>
      <table {...getTableProps()} style={{ width: "100%" }}>
        <thead>
          {headerGroups.map(headerGroup => (
            <tr {...headerGroup.getHeaderGroupProps()}>
              {headerGroup.headers.map(column => (
                <th {...column.getHeaderProps()}>{column.render("Header")}</th>
              ))}
            </tr>
          ))}
        </thead>
        <tbody {...getTableBodyProps()}>
          {currentPageData.map(row => {
            prepareRow(row);
            return (
              <tr {...row.getRowProps()}>
                {row.cells.map(cell => (
                  <td {...cell.getCellProps()}>{cell.render("Cell")}</td>
                ))}
              </tr>
            );
          })}
        </tbody>
      </table>

      <div>
        <button onClick={() => gotoPage(0)} disabled={!canPreviousPage}>
          {"<<"}
        </button>{" "}
        <button onClick={() => previousPage()} disabled={!canPreviousPage}>
          {"<"}
        </button>{" "}
        <button onClick={() => nextPage()} disabled={!canNextPage}>
          {">"}
        </button>{" "}
        <button onClick={() => gotoPage(pageOptions.length - 1)} disabled={!canNextPage}>
          {">>"}
        </button>{" "}
      </div>

      {/* Botão de exportação para CSV */}
      <CSVLink
        data={generateCSVData()}
        filename="dados_paginados.csv"
        className="btn btn-primary"
      >
        Exportar CSV
      </CSVLink>

      {/* Exemplo para alterar o número de itens por página */}
      <select
        value={pageSize}
        onChange={e => setPageSize(Number(e.target.value))}
      >
        <option value={5}>5</option>
        <option value={10}>10</option>
        <option value={20}>20</option>
      </select>
    </div>
  );
};

export default TableWithExport;
